'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var factory = require( './../lib/factory.js' );


// FIXTURES //

var positiveMean = require( './fixtures/julia/positive_mean.json' );
var negativeMean = require( './fixtures/julia/negative_mean.json' );
var largeVariance = require( './fixtures/julia/large_variance.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof factory, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns a function', function test( t ) {
	var quantile = factory( 0.0, 1.0 );
	t.strictEqual( typeof quantile, 'function', 'returns expected value' );
	t.end();
});

tape( 'if provided `NaN` for any parameter, the created function returns `NaN`', function test( t ) {
	var quantile;
	var y;

	quantile = factory( 0.0, 1.0 );
	y = quantile( NaN );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	quantile = factory( NaN, 1.0 );
	y = quantile( 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	quantile = factory( 1.0, NaN );
	y = quantile( 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	quantile = factory( NaN, NaN );
	y = quantile( 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	quantile = factory( NaN, NaN );
	y = quantile( NaN );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a finite `mu` and `c`, the function returns a function which returns `NaN` when provided a number outside `[0,1]` for `p`', function test( t ) {
	var quantile;
	var y;

	quantile = factory( 0.0, 1.0 );
	y = quantile( -0.1 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = quantile( 1.1 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a negative `c`, the created function always returns `NaN`', function test( t ) {
	var quantile;
	var y;

	quantile = factory( 0.0, -1.0 );

	y = quantile( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = quantile( 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	quantile = factory( 0.0, NINF );
	y = quantile( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	quantile = factory( PINF, NINF );
	y = quantile( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	quantile = factory( NINF, NINF );
	y = quantile( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	quantile = factory( NaN, NINF );
	y = quantile( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'the created function evaluates the quantile function at `p` given positive `mu`', function test( t ) {
	var expected;
	var quantile;
	var mu;
	var c;
	var p;
	var y;
	var i;

	expected = positiveMean.expected;
	p = positiveMean.p;
	mu = positiveMean.mu;
	c = positiveMean.c;
	for ( i = 0; i < p.length; i++ ) {
		quantile = factory( mu[i], c[i] );
		y = quantile( p[i] );
		if ( expected[i] !== null ) {
			t.strictEqual( isAlmostSameValue( y, expected[ i ], 33 ), true, 'returns expected value' );
		}
	}
	t.end();
});

tape( 'the created function evaluates the quantile function at `p` given negative `mu`', function test( t ) {
	var expected;
	var quantile;
	var mu;
	var c;
	var p;
	var y;
	var i;

	expected = negativeMean.expected;
	p = negativeMean.p;
	mu = negativeMean.mu;
	c = negativeMean.c;
	for ( i = 0; i < p.length; i++ ) {
		quantile = factory( mu[i], c[i] );
		y = quantile( p[i] );
		if ( expected[i] !== null ) {
			t.strictEqual( isAlmostSameValue( y, expected[ i ], 512 ), true, 'returns expected value' );
		}
	}
	t.end();
});

tape( 'the created function evaluates the quantile function at `p` given large variance ( = large `c`)', function test( t ) {
	var expected;
	var quantile;
	var mu;
	var c;
	var p;
	var y;
	var i;

	expected = largeVariance.expected;
	p = largeVariance.p;
	mu = largeVariance.mu;
	c = largeVariance.c;
	for ( i = 0; i < p.length; i++ ) {
		quantile = factory( mu[i], c[i] );
		y = quantile( p[i] );
		if ( expected[i] !== null ) {
			t.strictEqual( isAlmostSameValue( y, expected[ i ], 35 ), true, 'returns expected value' );
		}
	}
	t.end();
});
